powerpagecomponent.content:
{
  "source": "{% comment %}
sections--offering-detail

Purpose:
- Generic offering detail / capture template.
- Supports paid offerings with price options.
- Supports paid offerings with custom amount.
- Supports free / EOI offerings with no pricing.
- Always creates an Offering Acceptance, then redirects to the acceptance router.

Temporary note:
- CSS is embedded for testing.
- Class names are standardised for later extraction into shared CSS:
  - css--site / css--components for reusable primitives
  - css--theme-client for client/theme variables
  - section template only for section-specific layout if needed
{% endcomment %}

{% assign offering_id = '' %}

{% comment %}
Priority:
1. Offering selected on slot
2. Querystring offering id
{% endcomment %}

{% if slot.hit_offering %}
  {% assign offering_id = slot.hit_offering.id | default: slot.hit_offering | strip %}
{% endif %}

{% if offering_id == '' %}
  {% assign offering_id = request.params.id | default: '' | strip %}
{% endif %}

{% assign DEBUG = debug | default: request.params.debug == '1' %}

{% if DEBUG %}

  <div class="hit-offering-debug">
    sections--offering-detail debug<br><br>
    slot.hit_offering = {{ slot.hit_offering }}<br><br>
    slot.hit_offering.id = {{ slot.hit_offering.id }}<br><br>
    resolved offering_id = {{ offering_id }}
  </div>

{% endif %}

{% if offering_id == '' %}

  <div class="hit-alert hit-alert-warning" role="alert">
    Missing offering identifier.
  </div>

{% else %}

  {% fetchxml q %}
  <fetch mapping="logical" distinct="false">
    <entity name="hit_offering">
      <attribute name="hit_offeringid" />
      <attribute name="hit_offeringname" />
      <attribute name="hit_description" />
      <attribute name="hit_typelabel" />
      <attribute name="hit_summary" />
      <attribute name="hit_ctalabel" />
      <attribute name="hit_imageurl" />
      <attribute name="hit_isactive" />
        <attribute name="hit_offeringtype" />

      <filter>
        <condition attribute="hit_isactive" operator="eq" value="1" />
        <condition attribute="hit_offeringid" operator="eq" value="{{ offering_id | escape }}" />
      </filter>

      <link-entity name="hit_priceoption"
                   from="hit_offering"
                   to="hit_offeringid"
                   alias="po"
                   link-type="outer">

        <attribute name="hit_priceoptionid" />
        <attribute name="hit_impacttitle" />
        <attribute name="hit_impactdescription" />
        <attribute name="hit_amount" />

        <order attribute="hit_amount" />
      </link-entity>

    </entity>
  </fetch>
  {% endfetchxml %}

  {% assign rows = q.results.entities %}
  {% assign offering = rows | first %}

  {% if offering == nil %}

    <div class="hit-alert hit-alert-warning" role="alert">
      Offering not found or inactive.
    </div>

  {% else %}

    <style>
      /* Fallback overrides: ensure sticky CTA and rich-text marker styling even when shared CSS is stale/cached. */
      .hit-offering-detail .hit-rich-text-description li::marker {
        color: var(--hit-brand-primary, #007f89) !important;
        font-size: 3em !important;
      }

      @media (min-width: 992px) {
        .hit-offering-detail .hit-offering__capture {
          position: sticky !important;
          top: calc(var(--hit-header-offset, 80px) + .5rem) !important;
          align-self: start !important;
        }

        .hit-offering-detail .hit-capture-panel {
          position: static !important;
          max-height: calc(100vh - var(--hit-header-offset, 80px) - 1.5rem) !important;
          overflow-y: auto !important;
          overflow-x: hidden !important;
          z-index: 950 !important;
        }
      }
    </style>

    {% assign hasPricing = false %}
    {% assign offeringTypeLabel = '' %}
    {% assign freeTitle = 'Register your interest' %}
    {% assign freeSubtitle = 'Register your interest and we’ll keep you updated as more details become available.' %}
    {% assign formTitle = offering.hit_typelabel | default: freeTitle | strip %}
    {% assign formSummary = offering.hit_summary | default: freeSubtitle | strip %}
    {% assign ctaLabel = offering.hit_ctalabel | default: 'Continue' | strip %}

    {% if offering.hit_offeringtype and offering.hit_offeringtype.label %}
      {% assign offeringTypeLabel = offering.hit_offeringtype.label %}
    {% elsif offering['hit_offeringtype@OData.Community.Display.V1.FormattedValue'] %}
      {% assign offeringTypeLabel = offering['hit_offeringtype@OData.Community.Display.V1.FormattedValue'] %}
    {% elsif offering.hit_offeringtype %}
      {% assign offeringTypeLabel = offering.hit_offeringtype %}
    {% endif %}

    {% assign offeringTypeLabelNormalized = offeringTypeLabel | append: '' | strip | downcase %}

    {% if offeringTypeLabelNormalized == 'course' %}
      {% assign freeTitle = 'Sign up for access' %}
      {% assign freeSubtitle = 'Click the continue button below to complete your information and access The Hub.' %}
      {% if formTitle == '' %}
        {% assign formTitle = freeTitle %}
      {% endif %}
      {% if formSummary == '' %}
        {% assign formSummary = freeSubtitle %}
      {% endif %}
    {% endif %}

    {% if formTitle == '' %}
      {% assign formTitle = freeTitle %}
    {% endif %}
    {% if formSummary == '' %}
      {% assign formSummary = freeSubtitle %}
    {% endif %}

    {% for r in rows %}
      {% if r['po.hit_priceoptionid'] %}
        {% assign hasPricing = true %}
        {% break %}
      {% endif %}
    {% endfor %}

    <div class="hit-offering-detail"
         data-offeringid="{{ offering.hit_offeringid }}">

      <div class="hit-offering__shell">
        <div class="hit-offering__grid">

          <!-- LEFT: CONTENT -->
          <div class="hit-offering__content">



            {% if offering.hit_description != blank %}
              <div class="hit-offering__description hit-rich-text-description">
                {{ offering.hit_description }}
              </div>
            {% endif %}

          </div>

          <!-- RIGHT: CAPTURE -->
          <div class="hit-offering__capture">

            <div class="hit-card hit-capture-panel">

              {% if hasPricing %}

                <!-- PAID OFFERING -->
                {% if formTitle != blank %}
                  <h2 class="hit-form-card__title">
                    {{ formTitle }}
                  </h2>
                {% endif %}

                {% if formSummary != blank %}
                  <p class="hit-form-subtitle hit-eoi-msg">
                    {{ formSummary }}
                  </p>
                {% endif %}

                <div class="hit-status-pill">
                  Select an option to continue
                </div>

                <div class="hit-option-list hit-offering-options"
                     aria-label="Payment amount options">

                  {% for r in rows %}
                    {% if r['po.hit_priceoptionid'] %}

                      {% assign amt = r['po.hit_amount'] %}

                      {% if amt.value %}
                        {% assign amt = amt.value %}
                      {% endif %}

                      <button type="button"
                              class="hit-option-card hit-card hit-card--compact hit-card--interactive hit-fixed-opt"
                              data-amount="{{ amt }}"
                              data-priceoptionid="{{ r['po.hit_priceoptionid'] }}">

                        <div class="hit-option-card__content">

                          <div class="hit-option-card__header">
                            <div class="hit-selection-indicator" aria-hidden="true"></div>

                            <div class="hit-option-card__title">
                              {{ r['po.hit_impacttitle'] | default: 'Option' | escape }}
                            </div>
                          </div>

                          {% if r['po.hit_impactdescription'] != blank %}
                            <div class="hit-option-card__description">
                              {{ r['po.hit_impactdescription'] }}
                            </div>
                          {% endif %}

                        </div>

                        <div class="hit-option-card__amount">
                          ${{ amt }}
                        </div>

                      </button>

                    {% endif %}
                  {% endfor %}

                  <!-- CUSTOM AMOUNT OPTION -->
                  <div class="hit-option-card hit-card hit-card--compact hit-card--interactive hit-custom-opt"
                       role="button"
                       tabindex="0"
                       data-is-custom="true"
                       aria-label="Custom amount">

                    <div class="hit-selection-indicator" aria-hidden="true"></div>

                    <div class="hit-option-card__content">

                      <div class="hit-option-card__title">
                        Custom Amount
                      </div>

                      <div class="hit-option-card__description">
                        Enter an amount that is meaningful to you.
                      </div>

                      <div class="hit-custom-amount-row">
                        <span class="hit-custom-currency">$</span>

                        <input type="text"
                               inputmode="decimal"
                               autocomplete="off"
                               class="hit-input hit-input--pill hit-input--currency hit-custom-amount"
                               aria-label="Custom amount"
                               placeholder="Enter amount">
                      </div>

                      <div class="hit-custom-error" aria-live="polite"></div>

                    </div>

                  </div>

                </div>

                <div class="hit-actions">
                  <button type="button"
                          class="hit-button hit-button--primary continue-btn"
                          disabled>
                    <span class="btn-text">Continue</span>
                    <span class="btn-loading">
                      <span class="hit-spinner" aria-hidden="true"></span>
                      Creating...
                    </span>
                  </button>
                </div>

              {% else %}

                <!-- EOI / FREE OFFERING -->
                <div class="hit-offering-eoi">

                  <div class="hit-form-card">

                    <h2 class="hit-form-card__title">
                      {{ formTitle }}
                    </h2>

                    <p class="hit-form-subtitle hit-eoi-msg">
                      {{ formSummary }}
                    </p>

                  </div>

                  <div class="hit-actions">
                    <button type="button"
                            class="hit-button hit-button--primary eoi-btn">
                      <span class="btn-text">{{ ctaLabel }}</span>
                      <span class="btn-loading">
                        <span class="hit-spinner" aria-hidden="true"></span>
                        Creating...
                      </span>
                    </button>
                  </div>

                </div>

              {% endif %}

              <div class="hit-message hit-message--error hit-offering-error" role="alert"></div>

            </div>

          </div>

        </div>
      </div>

    </div>

    <script>
      (function(){

        const root = document.querySelector('.hit-offering-detail[data-offeringid="{{ offering.hit_offeringid }}"]');

        if (!root) {
          return;
        }

        let selectedMode = null;
        let selectedOpt = null;

        const offeringId = "{{ offering.hit_offeringid }}";

        function getContinueButton(){
          return root.querySelector(".continue-btn");
        }

        function getCustomCard(){
          return root.querySelector(".hit-custom-opt");
        }

        function getCustomInput(){
          return root.querySelector(".hit-custom-amount");
        }

        function getCustomError(){
          return root.querySelector(".hit-custom-error");
        }

        function getErrorBox(){
          return root.querySelector(".hit-offering-error");
        }

        function showError(message){
          const box = getErrorBox();

          if (!box) {
            alert(message);
            return;
          }

          box.textContent = message;
          box.style.display = "block";
        }

        function clearError(){
          const box = getErrorBox();

          if (!box) {
            return;
          }

          box.textContent = "";
          box.style.display = "none";
        }

        function parseAmount(raw){
          if (raw === null || raw === undefined) {
            return null;
          }

          const cleaned = String(raw)
            .replace(/[$,]/g, "")
            .trim();

          if (cleaned === "") {
            return null;
          }

          const amount = Number(cleaned);

          if (!Number.isFinite(amount)) {
            return null;
          }

          return Math.round(amount * 100) / 100;
        }

        function isValidAmount(amount){
          return amount !== null && amount > 0;
        }

        function clearSelection(){
          root.querySelectorAll(".hit-card--interactive").forEach(function(option){
            option.classList.remove("is-selected");
          });

          selectedMode = null;
          selectedOpt = null;
        }

        function selectFixedOption(option){
          clearError();
          clearSelection();

          option.classList.add("is-selected");

          selectedMode = "fixed";
          selectedOpt = option;

          const customInput = getCustomInput();
          const customError = getCustomError();

          if (customInput) {
            customInput.value = "";
          }

          if (customError) {
            customError.textContent = "";
          }

          updateContinueState();
        }

        function selectCustomOption(){
          clearError();

          const customCard = getCustomCard();

          clearSelection();

          if (customCard) {
            customCard.classList.add("is-selected");
          }

          selectedMode = "custom";
          selectedOpt = customCard;

          updateContinueState();
        }

        function getSelectedAmount(){
          if (selectedMode === "fixed" && selectedOpt) {
            return parseAmount(selectedOpt.dataset.amount);
          }

          if (selectedMode === "custom") {
            const customInput = getCustomInput();
            return parseAmount(customInput ? customInput.value : "");
          }

          return null;
        }

        function getSelectedPriceOptionId(){
          if (selectedMode === "fixed" && selectedOpt) {
            return selectedOpt.dataset.priceoptionid || "";
          }

          return "";
        }

        function updateContinueState(){
          const continueBtn = getContinueButton();
          const customError = getCustomError();

          if (!continueBtn) {
            return;
          }

          const amount = getSelectedAmount();
          const valid = isValidAmount(amount);

          continueBtn.disabled = !valid;

          if (selectedMode === "custom" && customError) {
            const customInput = getCustomInput();
            const hasValue = customInput && customInput.value.trim() !== "";

            customError.textContent = hasValue && !valid
              ? "Please enter an amount greater than $0."
              : "";
          }
        }

        async function getCsrfToken(){
          if (window.shell && typeof window.shell.getTokenDeferred === "function") {
            return new Promise(function(resolve){
              window.shell.getTokenDeferred()
                .done(function(token){
                  resolve(token || "");
                })
                .fail(function(){
                  resolve("");
                });
            });
          }

          const response = await fetch("/_layout/tokenhtml", {
            credentials: "same-origin"
          });

          const html = await response.text();
          const doc = new DOMParser().parseFromString(html, "text/html");
          const tokenInput = doc.querySelector("input[name='__RequestVerificationToken']");

          return tokenInput ? tokenInput.value : "";
        }

        async function createAcceptance(payload){
          const token = await getCsrfToken();

          if (!token) {
            throw new Error("Security token could not be loaded.");
          }

          const response = await fetch("/_api/hit_offeringacceptances", {
            method: "POST",
            credentials: "same-origin",
            headers: {
              "Content-Type": "application/json",
              "__RequestVerificationToken": token,
              "Accept": "application/json",
              "OData-MaxVersion": "4.0",
              "OData-Version": "4.0"
            },
            body: JSON.stringify(payload)
          });

          if (!response.ok) {
            let errorMessage = "Create failed.";

            try {
              const body = await response.json();

              if (body && body.error && body.error.message) {
                errorMessage = body.error.message;
              }
            } catch(jsonError) {
              try {
                const text = await response.text();

                if (text) {
                  errorMessage = text;
                }
              } catch(textError) {
                // Keep generic message.
              }
            }

            console.error("Create failed:", errorMessage);
            throw new Error(errorMessage);
          }

          const entityIdHeader =
            response.headers.get("entityid") ||
            response.headers.get("OData-EntityId") ||
            response.headers.get("odata-entityid");

          const match = entityIdHeader
            ? entityIdHeader.match(/[0-9a-fA-F-]{36}/)
            : null;

          return match ? match[0] : "";
        }

        function setButtonLoading(button, isLoading){
          if (!button) {
            return;
          }

          const text = button.querySelector(".btn-text");
          const loading = button.querySelector(".btn-loading");

          if (isLoading) {
            button.classList.add("is-loading");
            button.disabled = true;

            if (text) {
              text.style.display = "none";
            }

            if (loading) {
              loading.style.display = "inline-flex";
            }
          } else {
            button.classList.remove("is-loading");

            if (text) {
              text.style.display = "inline";
            }

            if (loading) {
              loading.style.display = "none";
            }
          }
        }

        function setPaidLoading(button, isLoading){
          setButtonLoading(button, isLoading);

          if (!isLoading) {
            updateContinueState();
          }
        }

        function buildAcceptanceUrl(acceptanceId){
          return window.location.origin +
            window.location.pathname +
            "?page=offering-acceptance&acceptanceid=" +
            encodeURIComponent(acceptanceId);
        }

        root.addEventListener("click", async function(event){

          clearError();

          /* SELECT FIXED PRICE OPTION */
          const fixedOption = event.target.closest("button.hit-fixed-opt");

          if (fixedOption && root.contains(fixedOption)) {
            selectFixedOption(fixedOption);
            return;
          }

          /* SELECT CUSTOM AMOUNT OPTION */
          const customCard = event.target.closest(".hit-custom-opt");

          if (customCard && root.contains(customCard)) {
            selectCustomOption();

            const customInput = getCustomInput();

            if (customInput && event.target !== customInput) {
              customInput.focus();
            }

            return;
          }

          /* CONTINUE - PAID OFFERING */
          const continueButton = event.target.closest(".continue-btn");

          if (continueButton && root.contains(continueButton)) {

            if (continueButton.classList.contains("is-loading")) {
              return;
            }

            const amount = getSelectedAmount();

            if (!isValidAmount(amount)) {
              updateContinueState();
              return;
            }

            setPaidLoading(continueButton, true);

            try {

              const payload = {
                "hit_Offering@odata.bind": "/hit_offerings(" + offeringId + ")",
                hit_baseamount: amount
              };

              const priceOptionId = getSelectedPriceOptionId();

              if (priceOptionId) {
                payload["hit_PriceOption@odata.bind"] =
                  "/hit_priceoptions(" + priceOptionId + ")";
              }

              const id = await createAcceptance(payload);

              if (!id) {
                throw new Error("No acceptance id returned from create.");
              }

              window.location.href = buildAcceptanceUrl(id);

            } catch (error) {

              console.error(error);
              showError(error.message || "Something went wrong. Please try again.");

              setPaidLoading(continueButton, false);
            }

            return;
          }

          /* EOI / FREE OFFERING */
          const eoiButton = event.target.closest(".eoi-btn");

          if (eoiButton && root.contains(eoiButton)) {

            if (eoiButton.classList.contains("is-loading")) {
              return;
            }

            setButtonLoading(eoiButton, true);

            try {

              const payload = {
                "hit_Offering@odata.bind": "/hit_offerings(" + offeringId + ")"
              };

              const id = await createAcceptance(payload);

              if (!id) {
                throw new Error("No acceptance id returned from create.");
              }

              window.location.href = buildAcceptanceUrl(id);

            } catch (error) {

              console.error(error);
              showError(error.message || "Something went wrong. Please try again.");

              setButtonLoading(eoiButton, false);
              eoiButton.disabled = false;
            }
          }

        });

        root.addEventListener("input", function(event){

          const customInput = event.target.closest(".hit-custom-amount");

          if (!customInput || !root.contains(customInput)) {
            return;
          }

          selectCustomOption();
          updateContinueState();

        });

        root.addEventListener("keydown", function(event){

          const customCard = event.target.closest(".hit-custom-opt");

          if (!customCard || !root.contains(customCard)) {
            return;
          }

          if (event.target.classList.contains("hit-custom-amount")) {
            return;
          }

          if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();

            selectCustomOption();

            const customInput = getCustomInput();

            if (customInput) {
              customInput.focus();
            }
          }

        });

      })();
    </script>

  {% endif %}

{% endif %}"
}
